/*
 * A278959  Length of the string that is generated by the concatenation of all
 *          the prime numbers < n.
 * https://oeis.org/A278959
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 499, u16 n <= 9403, u32 n <= 9403, u64 n <= 9403,
 *            u128 n <= 9403, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation of OEIS A278959: length of the string obtained by concatenating all primes < n.
   This implementation uses trial‑division to test for primality and a simple digit counter.
   It is valid C11 and C++17, uses only the standard headers <stdbool.h> and
   <stdint.h>, and does not rely on any external helper functions. */

#include <stdbool.h>
#include <stdint.h>

/* Return the number of decimal digits of a positive integer */
static inline int digit_len_idx(idx_t x)
{
    if (x == 0) return 1;   /* not used for primes, but defined for completeness */
    int len = 0;
    while (x != 0) {
        x /= 10;
        ++len;
    }
    return len;
}

/* Test whether a small integer is prime (for x >= 2) using trial division */
static inline bool is_prime_small(idx_t x)
{
    if (x < 2) return false;
    if (x == 2) return true;
    if ((x & 1u) == 0) return false;   /* even numbers > 2 are composite */
    for (idx_t d = 3; d * d <= x; d += 2) {
        if (x % d == 0) return false;
    }
    return true;
}

/* Sequence A278959: a(n) = length of concatenated string of all primes < n */
seq_t a(idx_t n)
{
    if (n <= 2u) return 0;   /* no primes less than 2 */
    seq_t total = 0;
    for (idx_t p = 2; p < n; ++p) {
        if (is_prime_small(p))
            total += (seq_t)digit_len_idx(p);
    }
    return total;
}
